challenge.solution:
def home():
    return "<h1>Home page</h1>"

def about():
    return "<h1>About</h1>"

routes = {"/": home, "/about": about}

def handle(path):
    if path in routes:
        return (200, routes[path]())
    return (404, "<h1>Not Found</h1>")

print(handle("/"))
print(handle("/secret"))
